const source=[
{date:'2026-10-27',chats:[{id:'product',name:'产品研发讨论群',kind:'group',count:126,first:'09:12',last:'21:35',avatar:'产'},{id:'ops',name:'AI 运营项目群',kind:'group',count:83,first:'10:08',last:'18:42',avatar:'AI'},{id:'wang',name:'小王',kind:'direct',count:34,first:'12:15',last:'20:06',avatar:'王'},{id:'chen',name:'小陈',kind:'direct',count:12,first:'08:32',last:'15:24',avatar:'陈'}]},
{date:'2026-10-26',chats:[{id:'product',name:'产品研发讨论群',kind:'group',count:92,first:'09:00',last:'19:40',avatar:'产'},{id:'wang',name:'小王',kind:'direct',count:28,first:'11:20',last:'22:18',avatar:'王'},{id:'release',name:'版本发布协作群',kind:'group',count:44,first:'13:06',last:'17:50',avatar:'版'}]},
{date:'2026-10-25',chats:[{id:'friends',name:'朋友聚餐群',kind:'group',count:47,first:'14:10',last:'21:30',avatar:'友'},{id:'chen',name:'小陈',kind:'direct',count:16,first:'10:05',last:'18:12',avatar:'陈'}]},
{date:'2026-10-23',chats:[{id:'ops',name:'AI 运营项目群',kind:'group',count:67,first:'09:30',last:'20:11',avatar:'AI'},{id:'li',name:'李工',kind:'direct',count:21,first:'15:02',last:'19:24',avatar:'李'}]},
{date:'2026-10-21',chats:[{id:'product',name:'产品研发讨论群',kind:'group',count:104,first:'08:48',last:'22:05',avatar:'产'},{id:'friends',name:'朋友聚餐群',kind:'group',count:31,first:'16:12',last:'20:18',avatar:'友'}]}];
const $=id=>document.getElementById(id);let kind='all',openDates=new Set(['2026-10-27']);let filtered=[];
const weekdays=['星期日','星期一','星期二','星期三','星期四','星期五','星期六'];
function dayLabel(s){const d=new Date(s+'T12:00:00');return `${s} · ${weekdays[d.getDay()]}`}
function apply(){const from=$('from').value,to=$('to').value;if(from&&to&&from>to){$('from').setCustomValidity('开始日期不能晚于结束日期');$('from').reportValidity();$('from').setCustomValidity('');return}filtered=source.filter(d=>(!from||d.date>=from)&&(!to||d.date<=to)).map(d=>({...d,chats:d.chats.filter(c=>kind==='all'||c.kind===kind)})).filter(d=>d.chats.length).sort((a,b)=>b.date.localeCompare(a.date));render()}
function render(){ $('dayCount').textContent=filtered.length+' 天';$('days').innerHTML='';$('empty').classList.toggle('hidden',!!filtered.length);$('days').classList.toggle('hidden',!filtered.length);filtered.forEach(d=>{const count=d.chats.reduce((s,c)=>s+c.count,0),expanded=openDates.has(d.date),day=d.date.slice(8,10),month=d.date.slice(5,7);const card=document.createElement('article');card.className='day';card.innerHTML=`<div class="day-head" role="button" tabindex="0" aria-expanded="${expanded}"><div class="datebox"><strong>${Number(day)}</strong><small>${Number(month)} 月</small></div><div class="day-title"><strong>${dayLabel(d.date)}</strong><small>${d.chats.length} 个聊天 · ${count.toLocaleString()} 条消息</small></div><div class="stats"><div class="stat"><span>聊天数量</span><b>${d.chats.length} 个</b></div><div class="stat"><span>消息总数</span><b>${count.toLocaleString()} 条</b></div></div><div class="chev">${expanded?'⌃':'⌄'}</div></div>${expanded?`<div class="chat-list">${d.chats.map(c=>`<div class="chat-row" role="button" tabindex="0" data-id="${c.id}" aria-label="打开 ${c.name}，${d.date}"><div class="avatar ${c.kind==='direct'?'direct':''}">${c.avatar}</div><div class="chat-info"><div class="chat-name-line"><span class="chat-name">${c.name}</span><span class="tag">${c.kind==='group'?'群聊':'私聊'}</span></div><div class="chat-sub">${c.first} 首条消息 · ${c.last} 最后消息</div></div><div class="chat-metrics"><span class="msg-count"><b>${c.count}</b> 条</span><span class="times">${c.first}–${c.last}</span><span class="arrow">›</span></div></div>`).join('')}</div>`:''}`;const head=card.querySelector('.day-head');const toggle=()=>{openDates.has(d.date)?openDates.delete(d.date):openDates.add(d.date);render()};head.addEventListener('click',toggle);head.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}});card.querySelectorAll('.chat-row').forEach(row=>{const c=d.chats.find(x=>x.id===row.dataset.id);const go=()=>detail(d.date,c);row.addEventListener('click',go);row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}})});$('days').appendChild(card)})}
function detail(date,c){$('footprint').classList.add('hidden');$('ai').classList.add('hidden');$('detail').classList.remove('hidden');$('pageTitle').textContent='聊天详情';$('subtitle').textContent='回忆定位 · 当前仅查看所选日期的聊天记录。';$('avatar').textContent=c.avatar;$('avatar').className='avatar '+(c.kind==='direct'?'direct':'');$('chatName').textContent=c.name;$('chatMeta').textContent=`${c.kind==='group'?'群聊':'私聊'} · ${date} · ${c.count} 条消息`;$('focusDate').textContent=`正在查看 ${date} 的聊天记录`;window.scrollTo({top:0,behavior:'smooth'})}
function back(){ $('detail').classList.add('hidden');$('ai').classList.add('hidden');$('footprint').classList.remove('hidden');$('pageTitle').textContent='搜索与问答';$('subtitle').textContent='按日期找回你聊过的群聊与私聊。';window.scrollTo({top:0,behavior:'smooth'})}
function showAi(){ $('footprint').classList.add('hidden');$('detail').classList.add('hidden');$('ai').classList.remove('hidden');$('pageTitle').textContent='搜索与问答';$('subtitle').textContent='AI 事件回顾保留现有功能。'}
$('apply').addEventListener('click',apply);$('from').addEventListener('change',apply);$('to').addEventListener('change',apply);document.querySelectorAll('.kind').forEach(b=>b.addEventListener('click',()=>{kind=b.dataset.kind;document.querySelectorAll('.kind').forEach(x=>x.classList.toggle('active',x===b));apply()}));$('reset').addEventListener('click',()=>{$('from').value='2026-10-01';$('to').value='2026-10-29';kind='all';document.querySelectorAll('.kind').forEach(b=>b.classList.toggle('active',b.dataset.kind==='all'));apply()});$('back').addEventListener('click',back);$('back2').addEventListener('click',back);$('back3').addEventListener('click',back);$('footTab').addEventListener('click',()=>{ $('footTab').classList.add('chosen');$('aiTab').classList.remove('chosen');back()});$('aiTab').addEventListener('click',()=>{$('aiTab').classList.add('chosen');$('footTab').classList.remove('chosen');showAi()});apply();